with remaining_keys as (select order_id from shipments intersect select order_id from shipments where cost <= 84), kept_rows as (select s.* from shipments s inner join remaining_keys k on s.order_id = k.order_id) select s.order_id, s.carrier, s.shipped_date, s.delivered_date, s.cost, s.status, case when carrier rlike '^(Kerry|DHL)$' then 'CORE' else 'EXTENDED' end as carrier_zone, (select sum(t2.quantity) from order_items t2 where t2.order_id = s.order_id) as sum_order_item_quantity from kept_rows s order by order_id;
